  ],
  "surfaces": [
    {
      "hex": "#000000",
      "name": "Void",
      "level": 0,
      "purpose": "Base canvas, page background, hero stage"
    },
    {
      "hex": "#1d1a1a",
      "name": "Charcoal",
      "level": 1,
